using System;
using System.IO;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using Object=UnityEngine.Object;
namespace CoastalFactory.Editor {
public static class StreetLightAssetBuilder {
 const string Root="Assets/_Anseong/Art/Environment/Assets/StreetLight";
 static readonly List<GameObject> parts=new List<GameObject>();static Material metal,dark,lens;
 static void Folder(string p){if(AssetDatabase.IsValidFolder(p))return;string parent=Path.GetDirectoryName(p).Replace('\\','/');Folder(parent);AssetDatabase.CreateFolder(parent,Path.GetFileName(p));}
 static Material Mat(string name,Color color){string p=Root+"/"+name+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(p);if(m)return m;m=new Material(Shader.Find("Universal Render Pipeline/Lit"));m.color=color;m.SetFloat("_Smoothness",.3f);m.enableInstancing=true;AssetDatabase.CreateAsset(m,p);return m;}
 static void Box(Transform root,string name,Vector3 pos,Vector3 size,Material mat){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=name;g.transform.SetParent(root,false);g.transform.localPosition=pos;g.transform.localScale=size;g.GetComponent<Renderer>().sharedMaterial=mat;Object.DestroyImmediate(g.GetComponent<Collider>());parts.Add(g);}
 static Mesh PoleMesh(){var v=new List<Vector3>();var t=new List<int>();const int n=12;for(int i=0;i<n;i++){float a=i*2*Mathf.PI/n,b=(i+1)*2*Mathf.PI/n;int k=v.Count;v.Add(new Vector3(Mathf.Cos(a)*.16f,.3f,Mathf.Sin(a)*.16f));v.Add(new Vector3(Mathf.Cos(a)*.085f,10.95f,Mathf.Sin(a)*.085f));v.Add(new Vector3(Mathf.Cos(b)*.085f,10.95f,Mathf.Sin(b)*.085f));v.Add(new Vector3(Mathf.Cos(b)*.16f,.3f,Mathf.Sin(b)*.16f));t.AddRange(new[]{k,k+1,k+2,k,k+2,k+3});}var m=new Mesh();m.SetVertices(v);m.SetTriangles(t,0);m.RecalculateNormals();return m;}
 static void Beam(Transform root,string name,Vector3 a,Vector3 b,float thickness,Material mat){Box(root,name,(a+b)*.5f,new Vector3(thickness,(b-a).magnitude,thickness),mat);parts[parts.Count-1].transform.localRotation=Quaternion.FromToRotation(Vector3.up,b-a);}
 [MenuItem("Anseong/Art/Build Street Light %#F10")]
 public static void Build(){Folder(Root);metal=Mat("GalvanizedSteel",new Color(.36f,.40f,.42f));dark=Mat("Housing",new Color(.09f,.12f,.14f));lens=Mat("LampLens",new Color(.87f,.9f,.79f));lens.EnableKeyword("_EMISSION");lens.SetColor("_EmissionColor",new Color(.7f,.75f,.55f)*1.4f);EditorUtility.SetDirty(lens);parts.Clear();var root=new GameObject("StreetLight");var r=root.transform;
  Box(r,"Footing",new Vector3(0,.15f,0),new Vector3(.65f,.3f,.65f),dark);Box(r,"BasePlate",new Vector3(0,.33f,0),new Vector3(.48f,.06f,.48f),metal);foreach(float x in new[]{-.17f,.17f})foreach(float z in new[]{-.17f,.17f})Box(r,"Bolt",new Vector3(x,.39f,z),new Vector3(.055f,.08f,.055f),dark);
  var pole=PoleMesh();var tube=new GameObject("TaperedPole");tube.transform.SetParent(r,false);tube.AddComponent<MeshFilter>().sharedMesh=pole;tube.AddComponent<MeshRenderer>().sharedMaterial=metal;parts.Add(tube);
  Box(r,"AccessPanel",new Vector3(0,1,.165f),new Vector3(.14f,.42f,.025f),dark);Beam(r,"RisingArm",new Vector3(0,10.9f,0),new Vector3(0,11.8f,1.05f),.12f,metal);Beam(r,"OutreachArm",new Vector3(0,11.8f,1.05f),new Vector3(0,11.85f,2.15f),.12f,metal);Box(r,"LampHousing",new Vector3(0,11.87f,2.05f),new Vector3(.48f,.26f,1.05f),dark);Box(r,"LEDLens",new Vector3(0,11.726f,2.05f),new Vector3(.38f,.025f,.86f),lens);
  var materials=new[]{metal,dark,lens};var intermediate=new List<Mesh>();var combined=new CombineInstance[3];for(int i=0;i<3;i++){var entries=new List<CombineInstance>();foreach(var p in parts)if(p.GetComponent<Renderer>().sharedMaterial==materials[i])entries.Add(new CombineInstance{mesh=p.GetComponent<MeshFilter>().sharedMesh,transform=r.worldToLocalMatrix*p.transform.localToWorldMatrix});var m=new Mesh();m.CombineMeshes(entries.ToArray(),true,true);intermediate.Add(m);combined[i]=new CombineInstance{mesh=m,transform=Matrix4x4.identity};}var mesh=new Mesh{name="StreetLight_LowPoly"};mesh.CombineMeshes(combined,false,true);mesh.RecalculateBounds();string path=Root+"/StreetLight.asset";var previous=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(previous){EditorUtility.CopySerialized(mesh,previous);Object.DestroyImmediate(mesh);mesh=previous;}else AssetDatabase.CreateAsset(mesh,path);foreach(var p in parts)Object.DestroyImmediate(p);foreach(var m in intermediate)Object.DestroyImmediate(m);Object.DestroyImmediate(pole);root.AddComponent<MeshFilter>().sharedMesh=mesh;root.AddComponent<MeshRenderer>().sharedMaterials=materials;var collision=root.AddComponent<BoxCollider>();collision.center=new Vector3(0,5.475f,0);collision.size=new Vector3(.34f,10.95f,.34f);var prefab=PrefabUtility.SaveAsPrefabAsset(root,Root+"/StreetLight.prefab");Object.DestroyImmediate(root);
  Folder("Assets/_Anseong/Scenes/Sandbox");EditorSceneManager.NewScene(NewSceneSetup.DefaultGameObjects,NewSceneMode.Single);PrefabUtility.InstantiatePrefab(prefab);var floor=GameObject.CreatePrimitive(PrimitiveType.Cube);floor.name="PreviewGround";floor.transform.position=new Vector3(0,-.1f,0);floor.transform.localScale=new Vector3(70,.2f,70);floor.GetComponent<Renderer>().sharedMaterial=metal;var camera=Camera.main;camera.transform.position=new Vector3(14,10,18);camera.transform.LookAt(new Vector3(0,6,1));camera.fieldOfView=40;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.22f,.30f,.38f);var sun=Object.FindFirstObjectByType<Light>();sun.intensity=2;sun.transform.rotation=Quaternion.Euler(40,-35,0);RenderSettings.ambientMode=UnityEngine.Rendering.AmbientMode.Flat;RenderSettings.ambientLight=new Color(.65f,.68f,.72f);EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene(),"Assets/_Anseong/Scenes/Sandbox/Sandbox_StreetLight.unity");AssetDatabase.SaveAssets();int tris=mesh.triangles.Length/3;if(tris>500||Mathf.Abs(mesh.bounds.max.y-12)>.02f||prefab.GetComponentsInChildren<Light>().Length!=0)throw new Exception("Street light validation failed");Capture(camera);Debug.Log("STREET_LIGHT_TEST_PASS triangles="+tris+" height="+mesh.bounds.max.y+" sharedMeshes=1 materials=3 realtimeLights=0");
 }
 static void Capture(Camera camera){var rt=new RenderTexture(900,1100,24);var old=RenderTexture.active;camera.targetTexture=rt;camera.Render();RenderTexture.active=rt;var image=new Texture2D(900,1100,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,900,1100),0,0);image.Apply();File.WriteAllBytes("C:/Users/Admin/Documents/ChatGPT/안성제철/output/StreetLight_Preview.png",image.EncodeToPNG());camera.targetTexture=null;RenderTexture.active=old;Object.DestroyImmediate(image);Object.DestroyImmediate(rt);}
}
